-- 558: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 5 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_558_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_558_guard;
INSERT INTO _migration_558_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_017' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The media are often described as the Fourth Estate because they...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Act as a watchdog over the Executive, Legislature and Judiciary","B. Form the fourth arm of government","C. Are owned entirely by the state","D. Control the decisions of the courts"]' AND q.correct_answer IS 'A' AND q.explanation IS 'By investigating and publicizing the actions of those in power, the media hold the three arms of government accountable — hence the label Fourth Estate. The media are not a formal arm of government, most Ghanaian media are privately owned, and court decisions remain the preserve of the Judiciary. Therefore the correct answer is A: Act as a watchdog over the Executive, Legislature and Judiciary.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_017' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_558_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_018' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is an example of print media in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An FM radio station","B. The Daily Graphic newspaper","C. A television news channel","D. A WhatsApp broadcast message"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Print media communicate through printed words and images — newspapers and magazines such as the Daily Graphic. Radio and television are electronic (broadcast) media, and WhatsApp messages are digital or new media, so neither category is print. Therefore the correct answer is B: The Daily Graphic newspaper.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_018' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_558_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_019' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a form of electronic media widely used in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A printed newspaper","B. A roadside billboard","C. FM radio broadcasting","D. A hand-written letter"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Electronic media transmit information by electronic signals — radio and television broadcasting reach most Ghanaian households. Newspapers and billboards are print and outdoor media respectively, and a hand-written letter is personal correspondence, not a mass medium. Therefore the correct answer is C: FM radio broadcasting.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_019' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_558_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_020' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of these is a social media platform commonly used by young Ghanaians?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The Ghana Broadcasting Corporation","B. The Daily Graphic","C. GTV","D. WhatsApp"]' AND q.correct_answer IS 'D' AND q.explanation IS 'WhatsApp is a social networking and messaging platform on which users create and share content. The Ghana Broadcasting Corporation, the Daily Graphic and GTV are traditional state or print media houses that produce one-way mass communication rather than interactive social networking. Therefore the correct answer is D: WhatsApp.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_020' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_017', 'topic_wassce_p2_soc_med', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The media are often described as the Fourth Estate because they...', 'multiple_choice', NULL, '["A. Act as a watchdog over the Executive, Legislature and Judiciary","B. Form the fourth arm of government","C. Are owned entirely by the state","D. Control the decisions of the courts"]', 'A', 'By investigating and publicizing the actions of those in power, the media hold the three arms of government accountable — hence the label Fourth Estate. The media are not a formal arm of government, most Ghanaian media are privately owned, and court decisions remain the preserve of the Judiciary. Therefore the correct answer is A: Act as a watchdog over the Executive, Legislature and Judiciary.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO1', NULL, NULL, 'board_waec');
